#!/usr/bin/env node
/** Validate generated bytes, shared schemas and recomputed counts. Never writes. */
import { resolve } from 'node:path'
import { verifyPack } from './lib/pack-files.mjs'

const manifestPath = resolve(process.argv[2] ?? 'packs/26.3/manifest.json')
try {
  const pack = await verifyPack(manifestPath)
  console.log(`✓ ${pack.manifest.id}: schema / counts / SHA-256 verified`)
} catch (error) {
  console.error(`✗ ${error.message}`)
  process.exitCode = 1
}
